import React, { useState, useEffect } from "react";
import "./CreateGroupPage.css";
import Navbar from "../components/navbar";
import Footer from "../components/footer";
import AdminSidebar from "../components/AdminSideBar";
import axios from "axios";

function CreateGroupPage() {
  const [groupNumber, setGroupNumber] = useState("");
  const [projectName, setProjectName] = useState("");
  const [selectedMembers, setSelectedMembers] = useState([]);
  const [supervisor, setSupervisor] = useState("");
  const [evaluator, setEvaluator] = useState("");
  const [allGroups, setAllGroups] = useState([]);
  const [students, setStudents] = useState([]);
  const [supervisors, setSupervisors] = useState([]);
  const [evaluators, setEvaluators] = useState([]);
  const [projects, setProjects] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [studentsRes, supervisorsRes, evaluatorsRes, projectsRes, groupsRes] = 
          await Promise.all([
            axios.get("http://localhost:5000/api/student"),
            axios.get("http://localhost:5000/api/facultyAdvisor"),
            axios.get("http://localhost:5000/api/evaluator"),
            axios.get("http://localhost:5000/api/project"),
            axios.get("http://localhost:5000/api/group")
          ]);

        setStudents(studentsRes.data.filter(s => !s.isGrouped));
        setSupervisors(supervisorsRes.data);
        setEvaluators(evaluatorsRes.data);
        setProjects(projectsRes.data);
        
        // Enrich groups with actual data
        const enrichedGroups = await Promise.all(
          groupsRes.data.map(async group => ({
            ...group,
            projectTitle: projectsRes.data.find(p => p._id === group.projectID)?.title,
            supervisorName: supervisorsRes.data.find(s => s.userId === group.supervisorID)?.Name,
            evaluatorName: evaluatorsRes.data.find(e => e.userId === group.evaluatorID)?.name
          }))
        );
        
        setAllGroups(enrichedGroups);
        setLoading(false);
      } catch (error) {
        console.error("Error fetching data:", error);
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleGroupCreation = async (e) => {
    e.preventDefault();
    
    if (!groupNumber || !projectName || selectedMembers.length === 0 || !supervisor || !evaluator) {
      alert("Please fill all fields and select members, supervisor, and evaluator.");
      return;
    }

    try {
      // Create project
      const projectRes = await axios.post("http://localhost:5000/api/project", {
        title: projectName,
        status: "Active"
      });

      // Create group
      const groupRes = await axios.post("http://localhost:5000/api/group", {
        groupNo: groupNumber,
        studentsRegno: selectedMembers.map(m => m.regNo),
        projectID: projectRes.data._id,
        supervisorID: supervisor,
        evaluatorID: evaluator
      });

      // Update students' grouped status
      await Promise.all(selectedMembers.map(member =>
        axios.put(`http://localhost:5000/api/student/${member.regNo}`, { isGrouped: true })
      ));

      // Update state
      const newGroup = {
        ...groupRes.data,
        projectTitle: projectName,
        supervisorName: supervisors.find(s => s.userId === supervisor)?.Name,
        evaluatorName: evaluators.find(e => e.userId === evaluator)?.name,
        studentsRegno: selectedMembers
      };

      setAllGroups([...allGroups, newGroup]);
      setStudents(students.filter(s => !selectedMembers.some(m => m.regNo === s.regNo)));
      resetForm();
    } catch (error) {
      console.error("Error creating group:", error);
      alert("Failed to create group. Please try again.");
    }
  };

  const handleDisbandGroup = async (groupId, projectId, members) => {
    if (!window.confirm("Are you sure you want to disband this group?")) return;

    try {
      await axios.delete(`http://localhost:5000/api/group/${groupId}`);
      await axios.delete(`http://localhost:5000/api/project/${projectId}`);
      
      // Reset students' grouped status
      await Promise.all(members.map(member =>
        axios.put(`http://localhost:5000/api/student/${member.regNo}`, { isGrouped: false })
      ));

      // Update state
      setAllGroups(allGroups.filter(g => g._id !== groupId));
      setStudents([...students, ...members]);
    } catch (error) {
      console.error("Error disbanding group:", error);
      alert("Failed to disband group. Please try again.");
    }
  };

  const resetForm = () => {
    setGroupNumber("");
    setProjectName("");
    setSelectedMembers([]);
    setSupervisor("");
    setEvaluator("");
  };

  const handleMemberSelection = (student) => {
    const isSelected = selectedMembers.some(m => m.regNo === student.regNo);
    if (isSelected) {
      setSelectedMembers(selectedMembers.filter(m => m.regNo !== student.regNo));
    } else if (selectedMembers.length < 4) {
      setSelectedMembers([...selectedMembers, student]);
    } else {
      alert("Maximum 4 members per group!");
    }
  };

  if (loading) return <div>Loading...</div>;

  return (
    <div className="create-group-container">
      <Navbar />
      <div className="content-wrapper">
        <AdminSidebar />
        <div className="main-content">
          <div className="create-group-section">
            {/* Group Form */}
            <div className="form-container">
              <h2>Create New Group</h2>
              <form onSubmit={handleGroupCreation}>
                <div className="input-group">
                  <label>Group Number</label>
                  <input
                    type="text"
                    value={groupNumber}
                    onChange={(e) => setGroupNumber(e.target.value)}
                    required
                  />
                </div>
                <div className="input-group">
                  <label>Project Name</label>
                  <input
                    type="text"
                    value={projectName}
                    onChange={(e) => setProjectName(e.target.value)}
                    required
                  />
                </div>
                
                {/* Supervisor and Evaluator Selection */}
                <div className="input-group">
                  <label>Supervisor</label>
                  <select
                    value={supervisor}
                    onChange={(e) => setSupervisor(e.target.value)}
                    required
                  >
                    <option value="">Select Supervisor</option>
                    {supervisors.map(s => (
                      <option key={s.userId} value={s.userId}>
                        {s.Name}
                      </option>
                    ))}
                  </select>
                </div>

                <div className="input-group">
                  <label>Evaluator</label>
                  <select
                    value={evaluator}
                    onChange={(e) => setEvaluator(e.target.value)}
                    required
                  >
                    <option value="">Select Evaluator</option>
                    {evaluators.map(e => (
                      <option key={e.userId} value={e.userId}>
                        {e.name}
                      </option>
                    ))}
                  </select>
                </div>

                <button type="submit" className="submit-button">
                  Create Group
                </button>
              </form>
            </div>

            {/* Student Selection */}
            <div className="student-selection">
              <h3>Available Students</h3>
              <table>
                <thead>
                  <tr>
                    <th>Select</th>
                    <th>Name</th>
                    <th>Reg. No</th>
                  </tr>
                </thead>
                <tbody>
                  {students.map(student => (
                    <tr key={student.regNo}>
                      <td>
                        <input
                          type="checkbox"
                          checked={selectedMembers.some(m => m.regNo === student.regNo)}
                          onChange={() => handleMemberSelection(student)}
                        />
                      </td>
                      <td>{student.studentName}</td>
                      <td>{student.regNo}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* Groups List */}
            <div className="groups-list">
              <h3>Existing Groups</h3>
              {allGroups.length > 0 ? (
                <table>
                  <thead>
                    <tr>
                      <th>Group No</th>
                      <th>Project</th>
                      <th>Supervisor</th>
                      <th>Evaluator</th>
                      <th>Members</th>
                      <th>Action</th>
                    </tr>
                  </thead>
                  <tbody>
                    {allGroups.map(group => (
                      <tr key={group._id}>
                        <td>{group.groupNo}</td>
                        <td>{group.projectTitle}</td>
                        <td>{group.supervisorName}</td>
                        <td>{group.evaluatorName}</td>
                        <td>
                          <ul>
                            {group.studentsRegno.map(member => (
                              <li key={member.regNo}>
                                {member.studentName} ({member.regNo})
                              </li>
                            ))}
                          </ul>
                        </td>
                        <td>
                          <button
                            className="disband-button"
                            onClick={() => handleDisbandGroup(
                              group._id,
                              group.projectID,
                              group.studentsRegno
                            )}
                          >
                            Disband
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              ) : (
                <p>No groups found</p>
              )}
            </div>
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
}

export default CreateGroupPage;
